#!/usr/bin/env bash
# Applies project settings to the Android files generated by `flutter create`.
set -euo pipefail

G=android/app/build.gradle
[ -f "$G" ] || G=android/app/build.gradle.kts
sed -i 's/minSdk = flutter.minSdkVersion/minSdk = 23/; s/minSdkVersion flutter.minSdkVersion/minSdkVersion 23/' "$G"

M=android/app/src/main/AndroidManifest.xml
grep -q 'android:allowBackup' "$M" || sed -i 's/<application/<application android:allowBackup="false"/' "$M"
sed -i 's/android:label="creator_crm"/android:label="Creator CRM"/' "$M"
# Internet is used only for the optional "auto-fill from product link" feature.
grep -q 'android.permission.INTERNET' "$M" || sed -i 's#<application#<uses-permission android:name="android.permission.INTERNET"/>\n    <application#' "$M"

S=android/settings.gradle
if [ -f "$S" ]; then
  sed -i 's/id "org.jetbrains.kotlin.android" version "[0-9.]*"/id "org.jetbrains.kotlin.android" version "1.9.24"/' "$S"
fi

cp tool/proguard-rules.pro android/app/proguard-rules.pro

echo "--- $G"; grep -n "minSdk" "$G" || true
echo "--- $M"; grep -n "<application" "$M" || true
